import type { Acl } from '../app'

type routeEnforceAcl =
    | {
          /**@deprecated List of ACLs that control access to this endpoint. */
          enforce_acl?: (string | ReturnType<typeof Acl>)[]
          enforceAcl?: never
      }
    | {
          /** List of ACLs that control access to this endpoint. */
          enforceAcl?: (string | ReturnType<typeof Acl>)[]
          enforce_acl?: never
      }

type routeShortDescription =
    | {
          /**@deprecated A brief description of the endpoint. */
          short_description?: string
          shortDescription?: never
      }
    | {
          /** A brief description of the endpoint. */
          shortDescription?: string
          short_description?: never
      }

type routeRequestExample =
    | {
          /**@deprecated An example request payload for the endpoint. */
          request_example?: string
          requestExample?: never
      }
    | {
          /** An example request payload for the endpoint. */
          requestExample?: string
          request_example?: never
      }

type protectionPolicy =
    | {
          /** @deprecated Use protectionPolicy instead. */
          policy?: '' | 'read' | 'protected'
          protectionPolicy?: never
      }
    | {
          /** The policy for how application files are protected when downloaded or installed. */
          protectionPolicy?: '' | 'read' | 'protected'
          policy?: never
      }

/**
 * Route definition for a REST API endpoint (`sys_ws_operation`).
 * @interface
 */
export type Route = Now.Internal.WithID<
    {
        /** The name of the endpoint. This is displayed in the API documentation. */
        name?: string

        /** The script that processes the request and generates a response. Consider using a Server Module or `Now.include()` to move the script to a separate js file.*/
        script: ((request: any, response: any) => void) | string

        /** The HTTP method for the endpoint. Defaults to 'GET' if not specified. */
        method?: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE'

        /** The URL path for the endpoint, relative to the API's base URL. */
        path?: string

        /** If true, the endpoint is active and can receive requests. */
        active?: boolean

        /** MIME type that the endpoint can consume. */
        consumes?: string

        /** MIME type that the endpoint produces. */
        produces?: string

        /** If true, the endpoint requires authorization. */
        authorization?: boolean

        /** If true, the endpoint requires authentication. */
        authentication?: boolean

        /** If true, the endpoint is only accessible to users with the internal role. */
        internalRole?: boolean

        /** List of parameters that the endpoint accepts. */
        parameters?: RouteParameter[]

        /** List of headers that the endpoint accepts or requires. */
        headers?: RouteHeader[]
    } & (routeEnforceAcl & routeShortDescription & routeRequestExample & protectionPolicy)
>

type parameterExampleValue =
    | {
          /**@deprecated An example value for the parameter. */
          example_value?: string
          exampleValue?: never
      }
    | {
          /** An example value for the parameter. */
          exampleValue?: string
          example_value?: never
      }

type parameterShortDescription =
    | {
          /**@deprecated A brief description of the parameter. */
          short_description?: string
          shortDescription?: never
      }
    | {
          /** A brief description of the parameter. */
          shortDescription?: string
          short_description?: never
      }

/**
 * Parameter definition for a REST API route (`sys_ws_operation`).
 * @interface
 */
export type RouteParameter = Now.Internal.WithID<
    {
        /** The name of the parameter. */
        name: string

        /** Indicates whether the parameter is required for the request. */
        required?: boolean
    } & parameterExampleValue &
        parameterShortDescription
>

type headerExampleValue =
    | {
          /**@deprecated An example value for the header. */
          example_value?: string
          exampleValue?: never
      }
    | {
          /** An example value for the header. */
          exampleValue?: string
          example_value?: never
      }

type headerShortDescription =
    | {
          /**@deprecated A brief description of the header. */
          short_description?: string
          shortDescription?: never
      }
    | {
          /** A brief description of the header. */
          shortDescription?: string
          short_description?: never
      }

/**
 * Header definition for a REST API route (`sys_ws_operation`).
 * @interface
 */
export type RouteHeader = Now.Internal.WithID<
    {
        /** The name of the header. */
        name: string

        /** Indicates whether the header is required for the request. */
        required?: boolean
    } & headerExampleValue &
        headerShortDescription
>

type versionIsDefault =
    | {
          /**@deprecated Indicates whether this is the default version of the API. */
          is_default?: boolean
          isDefault?: never
      }
    | {
          /** Indicates whether this is the default version of the API. */
          isDefault?: boolean
          is_default?: never
      }

type versionShortDescription =
    | {
          /**@deprecated A brief description of the API version. */
          short_description?: string
          shortDescription?: never
      }
    | {
          /** A brief description of the API version. */
          shortDescription?: string
          short_description?: never
      }

/**
 * Version definition for a REST API (`sys_ws_version`).
 * @interface
 */
export type ApiVersion<I extends number = number> = Now.Internal.WithID<
    {
        /** The version number of the API. */
        version: I
        /** Indicates whether the API version is active and can receive requests. */
        active?: boolean
        /** Indicates whether the API version is deprecated. */
        deprecated?: boolean
    } & versionIsDefault &
        versionShortDescription
>

type restEnforceAcl =
    | {
          /**@deprecated A list of ACLs to enforce when accessing resources (`sys_security_acl`) */
          enforce_acl?: (string | ReturnType<typeof Acl>)[]
          enforceAcl?: never
      }
    | {
          /** A list of ACLs to enforce when accessing resources (`sys_security_acl`) */
          enforceAcl?: (string | ReturnType<typeof Acl>)[]
          enforce_acl?: never
      }

type restServiceId =
    | {
          /**@deprecated The API identifier used to distinguish this API in URI paths. It must be unique within the API namespace */
          service_id: string
          serviceId?: never
      }
    | {
          /** The API identifier used to distinguish this API in URI paths. It must be unique within the API namespace */
          serviceId: string
          service_id?: never
      }

type restShortDescription =
    | {
          /**@deprecated A brief description of the API, which is used in the API documentation */
          short_description?: string
          shortDescription?: never
      }
    | {
          /** A brief description of the API, which is used in the API documentation */
          shortDescription?: string
          short_description?: never
      }

type restDocLink =
    | {
          /**@deprecated A URL that links to static documentation about the API */
          doc_link?: string
          docLink?: never
      }
    | {
          /** A URL that links to static documentation about the API */
          docLink?: string
          doc_link?: never
      }

/** @interface */
export type RestApi<I extends number, V extends ApiVersion<I>> = Now.Internal.WithID<
    {
        /** The name of the API, which is used in the API documentation. */
        name: string
        /** Indicates whether the API can serve requests */
        active?: boolean
        /** A list of media types that resources of the API can consume */
        consumes?: string
        /** A list of media types that resources of the API can produce */
        produces?: string
    } & (restEnforceAcl & restShortDescription & restServiceId & restDocLink & protectionPolicy & Now.Internal.Meta) &
        Now.Internal.OverrideProperties
> &
    (
        | {
              /** The resources (`sys_ws_operation`) for the API */
              routes?: (Route & { version: V['version'] })[]
              /** A list of versions (`sys_ws_version`) for the API */
              versions: ApiVersion<I>[]
          }
        | {
              /** The resources (`sys_ws_operation`) for the API */
              routes?: Route[]
              /** A list of versions (`sys_ws_version`) for the API */
              versions?: never
          }
    )

/**
 * Creates endpoints, query parameters, and headers for a scripted REST service (`sys_ws_definition`).
 *
 * @see https://docs.servicenow.com/csh?topicname=scripted-rest-api-api-now-ts.html&version=latest
 *
 * @param config - an object containing the following properties:
 *   * **$id** - unique id for the record, typically using `Now.ID["value"]`
 *   * **name** - the name of the API, which is used in the API documentation
 *   * **serviceId** - the API identifier used to distinguish this API in URI paths. It must be unique within the API namespace
 *   * **active**? - indicates whether the API can serve requests
 *   * **consumes**? - a list of media types that resources of the API can consume
 *   * **docLink**? - a URL that links to static documentation about the API
 *   * **enforceAcl**? - a list of variable identifiers of ACL objects or `sys_id`s of ACLs to enforce when accessing resources (`sys_security_acl`)
 *   * **protectionPolicy**? - the policy for how application files are protected when downloaded or installed
 *   * **produces**? - a list of media types that resources of the API can produce
 *   * **routes**? - the resources (`sys_ws_operation`) for the API
 *   * **shortDescription**? - a brief description of the API, which is used in the API documentation
 *   * **versions?** - a list of versions (`sys_ws_version`) for the API
 */
export function RestApi<I extends number, V extends ApiVersion<I>>(api: RestApi<I, V>) {
    return api
}
